package mx.com.mesaregia.inventario.api.controller;
import jakarta.validation.Valid; import mx.com.mesaregia.inventario.application.service.CorteFisicoService; import mx.com.mesaregia.inventario.api.request.*; import mx.com.mesaregia.inventario.api.response.*; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
import org.springframework.data.web.PageableDefault;
@RestController @RequestMapping("/api/v1/inventario/cortes") public class CorteController {private final CorteFisicoService s;public CorteController(CorteFisicoService s){this.s=s;} @GetMapping @PreAuthorize("hasAuthority('inventario.cortes.consultar')")public PageResponse<CorteResponse> buscar(@PageableDefault(size=20)Pageable p){return s.buscar(p);}@GetMapping("/{id}")@PreAuthorize("hasAuthority('inventario.cortes.consultar')")public CorteResponse get(@PathVariable Long id){return s.obtener(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('inventario.cortes.gestionar')")public CorteResponse post(@Valid @RequestBody CorteIniciarRequest r){return s.iniciar(r);}@PutMapping("/{id}/conteos")@PreAuthorize("hasAuthority('inventario.cortes.gestionar')")public CorteResponse conteos(@PathVariable Long id,@Valid @RequestBody CorteConteosRequest r){return s.registrarConteos(id,r);}@PostMapping("/{id}/cerrar")@PreAuthorize("hasAuthority('inventario.cortes.gestionar')")public CorteResponse cerrar(@PathVariable Long id,@Valid @RequestBody CorteCerrarRequest r){return s.cerrar(id,r);} }
